46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        this.clinicService.saveOwner(owner);
105	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
106	        headers.setLocation(UriComponentsBuilder.newInstance()
107	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
108	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
114	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
115	        if (currentOwner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        currentOwner.setAddress(ownerFieldsDto.getAddress());
119	        currentOwner.setCity(ownerFieldsDto.getCity());
120	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
121	        currentOwner.setLastName(ownerFieldsDto.getLastName());
122	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
123	        this.clinicService.saveOwner(currentOwner);
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Transactional
129	    @Override
130	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
131	        Owner owner = this.clinicService.findOwnerById(ownerId);
132	        if (owner == null) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        this.clinicService.deleteOwner(owner);
136	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        HttpHeaders headers = new HttpHeaders();
147	        Pet pet = petMapper.toPet(petFieldsDto);
148	        owner.setId(ownerId);
149	        pet.setOwner(owner);
150	        pet.getType().setName(null);
151	        this.clinicService.savePet(pet);
152	        PetDto petDto = petMapper.toPetDto(pet);
153	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
154	            .buildAndExpand(pet.getId()).toUri());
155	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
161	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
162	        if (currentOwner != null) {
163	            Pet currentPet = this.clinicService.findPetById(petId);
164	            if (currentPet != null) {
165	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
166	                currentPet.setName(petFieldsDto.getName());
167	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
168	                this.clinicService.savePet(currentPet);
169	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
170	            }
171	        }
172	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
178	        HttpHeaders headers = new HttpHeaders();
179	        Visit visit = visitMapper.toVisit(visitFieldsDto);
180	        Pet pet = new Pet();
181	        pet.setId(petId);
182	        visit.setPet(pet);
183	        this.clinicService.saveVisit(visit);
184	        VisitDto visitDto = visitMapper.toVisitDto(visit);
185	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
186	            .buildAndExpand(visit.getId()).toUri());
187	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
188	    }
189	
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
194	        Owner owner = this.clinicService.findOwnerById(ownerId);
195	        if (owner != null) {
196	            Pet pet = owner.getPet(petId);
197	            if (pet != null) {
198	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
199	            }
200	        }
201	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	    }
203	}
