34	/**
35	 * Normalizes an owner's telephone to E.164 before the request reaches the controller: a
36	 * leading '+' keeps its country code, otherwise country code '+61' is assumed and a single
37	 * leading '0' dropped; spaces, dashes and brackets are stripped and 8 to 15 digits must
38	 * remain after the '+' or the request is rejected with a 400. Kept as its own advice so
39	 * this rule stays a small, self-contained unit rather than growing the controller or another
40	 * handler.
41	 */
42	@ControllerAdvice
43	@Order(Ordered.HIGHEST_PRECEDENCE)
44	public class OwnerTelephoneNormalizationAdvice extends RequestBodyAdviceAdapter {
45	
46	    @Override
47	    public boolean supports(MethodParameter methodParameter, Type targetType,
48	                            Class<? extends HttpMessageConverter<?>> converterType) {
49	        return OwnerFieldsDto.class.equals(targetType);
50	    }
51	
52	    @Override
53	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
54	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
55	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
56	        owner.setTelephone(toE164(owner.getTelephone()));
57	        return body;
58	    }
59	
60	    /** Converts a telephone to its E.164 string, or throws when no valid form exists. */
61	    static String toE164(String telephone) {
62	        String trimmed = telephone == null ? "" : telephone.trim();
63	        String digits = trimmed.replaceAll("\\D", "");
64	        if (!trimmed.startsWith("+")) {
65	            if (digits.startsWith("0")) {
66	                digits = digits.substring(1);
67	            }
68	            digits = "61" + digits;
69	        }
70	        if (digits.length() < 8 || digits.length() > 15) {
71	            throw new InvalidTelephoneException();
72	        }
73	        return "+" + digits;
74	    }
75	
76	    @ExceptionHandler(InvalidTelephoneException.class)
77	    @ResponseBody
78	    public ResponseEntity<String> handleInvalidTelephone(InvalidTelephoneException e) {
79	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(e.getMessage());
80	    }
81	
82	    /** Signals a telephone that cannot form a valid E.164 number. */
83	    static class InvalidTelephoneException extends RuntimeException {
84	
85	        InvalidTelephoneException() {
86	            super("telephone must form a valid E.164 number");
87	        }
88	    }
89	}
