98	        return new HttpInputMessage() {
99	            @Override
100	            public InputStream getBody() {
101	                return new ByteArrayInputStream(body);
102	            }
103	
104	            @Override
105	            public HttpHeaders getHeaders() {
106	                return headers;
107	            }
108	        };
109	    }
