38	/**
39	 * Rejects creating an owner once 100 or more owners already share the request's effective
40	 * registration business day (by registrationDate), answering 429. Kept as its own advice so
41	 * this rule stays a small,
42	 * self-contained unit rather than growing the controller or another handler.
43	 */
44	@ControllerAdvice
45	@Order(Ordered.HIGHEST_PRECEDENCE)
46	public class OwnerDailyCreationLimitAdvice extends RequestBodyAdviceAdapter {
47	
48	    private static final int DAILY_LIMIT = 100;
49	
50	    private final ClinicService clinicService;
51	
52	    public OwnerDailyCreationLimitAdvice(ClinicService clinicService) {
53	        this.clinicService = clinicService;
54	    }
55	
56	    @Override
57	    public boolean supports(MethodParameter methodParameter, Type targetType,
58	                            Class<? extends HttpMessageConverter<?>> converterType) {
59	        Method method = methodParameter.getMethod();
60	        return OwnerFieldsDto.class.equals(targetType)
61	            && method != null && "addOwner".equals(method.getName());
62	    }
63	
64	    @Override
65	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
66	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
67	        LocalDate businessDay = RegistrationBusinessDay.effective(((OwnerFieldsDto) body).getRegistrationDate());
68	        long count = clinicService.findAllOwners().stream()
69	            .map(Owner::getRegistrationDate)
70	            .filter(businessDay::equals)
71	            .count();
72	        if (count >= DAILY_LIMIT) {
73	            throw new DailyLimitReachedException();
74	        }
75	        return body;
76	    }
77	
78	    @ExceptionHandler(DailyLimitReachedException.class)
79	    @ResponseBody
80	    public ResponseEntity<String> handleDailyLimitReached(DailyLimitReachedException e) {
81	        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body(e.getMessage());
82	    }
83	
84	    /** Signals that the maximum number of owners for today has already been created. */
85	    static class DailyLimitReachedException extends RuntimeException {
86	
87	        DailyLimitReachedException() {
88	            super("daily owner creation limit reached");
89	        }
90	    }
91	}
